sed -i '' -e 's/func quickConsumeOne(from group: StockGroup) async -> Bool/func quickConsumeOne(item: StockItemSnapshot) async -> Bool {\n        guard !isMoving else { return false }\n        let quantityToConsume = min(item.currentQuantity, item.key.unit.defaultStep)\n        isMoving = true\n        defer { isMoving = false }\n        do {\n            try await inventory.consume(item.id, quantity: quantityToConsume)\n        } catch {\n            errorMessage = "Impossibile consumare l\'alimento: riprova."\n            return false\n        }\n        await refreshAfterConsumption()\n        return true\n    }\n\n    \/\/\/ Consuma rapidamente un\'unità dalla confezione più vicina alla scadenza all all\'apertura nel gruppo specificato.\n    func quickConsumeOne(from group: StockGroup) async -> Bool/g' Frigo/Cibo/Features/Fridge/FridgeViewModel.swift
sed -i '' -e 's/func discardWhole(from group: StockGroup) async -> Bool/func discardWhole(item: StockItemSnapshot) async -> Bool {\n        guard !isMoving else { return false }\n        isMoving = true\n        defer { isMoving = false }\n        do {\n            try await inventory.consume(item.id, quantity: item.currentQuantity)\n        } catch {\n            errorMessage = "Errore durante la rimozione dell\'alimento."\n            return false\n        }\n        await refreshAfterConsumption()\n        return true\n    }\n\n    \/\/\/ Butta o rimuove interamente la confezione più vicina alla scadenza.\n    func discardWhole(from group: StockGroup) async -> Bool/g' Frigo/Cibo/Features/Fridge/FridgeViewModel.swift
